/* Token Radar dashboard: dark ink, amber signal, one column, no framework. */
:root {
  --ink: #101828; --ink-2: #344054; --muted: #667085; --line: #e4e7ec;
  --bg: #f8fafc; --card: #ffffff; --amber: #b54708; --amber-bg: #fffaeb;
  --green: #067647; --green-bg: #ecfdf3; --red: #b42318; --red-bg: #fef3f2;
  --navy: #0b2239; --navy-2: #14365a; --gold: #f79009;
  --radius: 12px; --font: system-ui, -apple-system, "Segoe UI", sans-serif;
}
* { box-sizing: border-box; }
body { margin: 0; background: var(--bg); color: var(--ink); font: 15px/1.5 var(--font); }
.skip { position: absolute; left: -999px; top: 0; background: var(--navy); color: #fff; padding: 8px 12px; z-index: 9; }
.skip:focus { left: 8px; top: 8px; }
.shell { max-width: 1080px; margin: 0 auto; padding: 0 20px 48px; }
.top { display: flex; justify-content: space-between; align-items: center; padding: 18px 0 6px; gap: 16px; flex-wrap: wrap; }
.brand { display: flex; align-items: center; gap: 10px; font-weight: 800; font-size: 20px; letter-spacing: -0.02em; }
.mark { width: 26px; height: 26px; border-radius: 8px; background: var(--gold); display: inline-block; box-shadow: inset 0 -8px 0 rgba(0, 0, 0, 0.18); }
.top-meta { display: flex; gap: 8px; flex-wrap: wrap; }
.top-meta span { background: var(--card); border: 1px solid var(--line); border-radius: 999px; padding: 4px 10px; font-size: 12.5px; color: var(--ink-2); }
.lede { background: var(--navy); color: #eef2f6; border-radius: var(--radius); padding: 22px 24px; margin: 12px 0 16px; }
.lede h1 { margin: 0 0 6px; font-size: 24px; line-height: 1.25; letter-spacing: -0.02em; }
.lede p { margin: 0; color: #b8c4d1; max-width: 720px; }
.facts { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: 16px; }
.fact { background: var(--navy-2); border-radius: 10px; padding: 10px 12px; }
.fact span { display: block; font-size: 12px; color: #9fb0c3; }
.fact b { font-size: 19px; }
.top10 { margin-top: 16px; }
.top10 h2 { font-size: 13px; text-transform: uppercase; letter-spacing: 0.06em; color: #9fb0c3; margin: 0 0 8px; }
.top10 .row { display: grid; grid-template-columns: 190px 1fr 76px; gap: 10px; align-items: center; font-size: 13px; padding: 2px 0; }
.top10 .bar { height: 8px; background: #1e3a5c; border-radius: 4px; overflow: hidden; }
.top10 .bar i { display: block; height: 100%; background: var(--gold); border-radius: 4px; }
.top10 .num { text-align: right; font-variant-numeric: tabular-nums; }
.controls { display: flex; gap: 14px; align-items: flex-end; flex-wrap: wrap; margin: 0 0 12px; }
.field label, .field .sub { display: block; font-size: 12.5px; color: var(--muted); margin-bottom: 4px; }
.field input, .field select { font: inherit; padding: 8px 10px; border: 1px solid var(--line); border-radius: 8px; background: var(--card); color: var(--ink); min-width: 190px; }
.field input:focus, .field select:focus { outline: 2px solid var(--gold); outline-offset: 1px; }
.tabs { display: flex; gap: 6px; }
.tabs button { font: inherit; padding: 8px 14px; border: 1px solid var(--line); border-radius: 999px; background: var(--card); cursor: pointer; }
.tabs button[aria-pressed="true"] { background: var(--navy); color: #fff; border-color: var(--navy); }
.check { display: flex; align-items: center; gap: 6px; font-size: 13.5px; padding-bottom: 8px; }
.check input { width: 16px; height: 16px; accent-color: var(--amber); }
.count { margin-left: auto; font-size: 13px; color: var(--muted); align-self: center; }
.panel { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); margin-bottom: 16px; }
.table-wrap { overflow-x: auto; }
table { border-collapse: collapse; width: 100%; font-size: 14px; }
caption { text-align: left; padding: 12px 16px 0; color: var(--muted); font-size: 13px; }
th, td { padding: 9px 12px; text-align: left; border-top: 1px solid var(--line); vertical-align: middle; }
thead th { border-top: 0; font-size: 12.5px; color: var(--muted); }
th button { all: unset; cursor: pointer; font-weight: 600; color: var(--muted); }
th button:hover { color: var(--ink); }
tbody tr { cursor: pointer; }
tbody tr:hover { background: #f9fafb; }
tbody tr[data-selected="true"] { background: var(--amber-bg); }
.num { font-variant-numeric: tabular-nums; text-align: right; white-space: nowrap; }
.name b { display: block; font-size: 14.5px; }
.sub { color: var(--muted); font-size: 12.5px; }
.pos { color: var(--green); } .neg { color: var(--red); }
.implied .bar { height: 6px; background: #eef1f4; border-radius: 3px; overflow: hidden; margin-bottom: 3px; }
.implied .bar i { display: block; height: 100%; background: var(--gold); }
.badge { display: inline-block; font-size: 11px; font-weight: 700; color: var(--amber); background: var(--amber-bg); border: 1px solid #fedf89; border-radius: 999px; padding: 1px 7px; margin-left: 6px; vertical-align: 1px; }
.status { display: inline-block; font-size: 12px; background: var(--green-bg); color: var(--green); border-radius: 999px; padding: 2px 9px; white-space: nowrap; }
.status.live { background: #eef4ff; color: #175cd3; }
.empty { padding: 32px 24px; text-align: center; }
.empty h2 { margin: 0 0 6px; }
.button { font: inherit; padding: 9px 16px; border-radius: 8px; border: 1px solid var(--line); background: var(--card); cursor: pointer; }
.button.primary { background: var(--navy); color: #fff; border-color: var(--navy); }
.model { padding: 20px 22px; }
.model h2, .sandbox h2 { margin: 0 0 6px; font-size: 18px; }
.model p { margin: 8px 0; }
.formula { background: var(--bg); border: 1px solid var(--line); border-radius: 8px; padding: 12px 14px; font-family: ui-monospace, monospace; font-size: 13px; overflow-x: auto; white-space: nowrap; }
.caltable { width: 100%; font-size: 13.5px; margin-top: 10px; }
.caltable th, .caltable td { padding: 6px 8px; }
.sandbox { padding: 20px 22px; }
.sandbox .sliders { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin: 12px 0; }
.sandbox label { display: block; font-size: 13px; font-weight: 600; margin-bottom: 4px; }
.sandbox input[type="range"] { width: 100%; accent-color: var(--amber); }
.sandbox .note { background: var(--amber-bg); border: 1px solid #fedf89; border-radius: 8px; padding: 10px 12px; font-size: 13px; }
.detail { border: 0; border-radius: 14px; padding: 0; max-width: 640px; width: calc(100vw - 40px); box-shadow: 0 20px 60px rgba(16, 24, 40, 0.35); }
.detail::backdrop { background: rgba(16, 24, 40, 0.55); }
.detail-head { display: flex; justify-content: space-between; gap: 16px; padding: 20px 22px 0; }
.detail-head h2 { margin: 4px 0; font-size: 22px; }
.close { all: unset; cursor: pointer; border: 1px solid var(--line); border-radius: 8px; padding: 6px 12px; height: fit-content; font-size: 13px; }
.detail-section { padding: 8px 22px 20px; }
.detail-section h3 { margin: 10px 0 8px; font-size: 15px; }
.equation { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 20px; }
.equation > div { display: flex; justify-content: space-between; border-bottom: 1px solid var(--line); padding: 6px 0; }
.equation span { color: var(--muted); font-size: 13px; }
.steps { margin: 0; padding-left: 20px; }
.steps li { margin-bottom: 10px; }
.steps li b { display: block; font-weight: 600; }
.steps .cost { color: var(--muted); font-size: 13px; }
.note-small { font-size: 12.5px; color: var(--muted); }
@media (max-width: 720px) {
  .facts { grid-template-columns: repeat(2, 1fr); }
  .sandbox .sliders { grid-template-columns: 1fr; }
  .equation { grid-template-columns: 1fr; }
  .top10 .row { grid-template-columns: 120px 1fr 64px; }
}
